WITH unpacked AS (SELECT id, customer_id, created_at, ship_to, attributes['device'] AS device, AGGREGATE(items, 0.0D, (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS basket_amount, SIZE(FILTER(items, i -> i.qty >= 3)) AS bulk_lines, TRANSFORM(items, i -> i.product_id) AS product_ids, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts WHERE customer_id IN (12, 33)) SELECT *, COUNT(bulk_lines) OVER w_part AS last3_count_bulk_lines, MAX(bulk_lines) OVER w_part AS last3_max_bulk_lines, SUM(bulk_lines) OVER w_part AS last3_sum_bulk_lines, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY basket_amount DESC, id) AS seq_no FROM unpacked WINDOW w_part AS (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
